function isValidPrime(arr) {
  // Check if all elements in the array are integers
  if (!Array.isArray(arr) || !arr.every(num => Number.isInteger(num))) {
    return false;
  }

  // Check if any element is not a positive integer
  for (let I = 0; I < arr.length; i++) {
    if (Number.isNaN(arr[i]) || arr[i] <= 0) {
      return false;
    }
  }

